(() => {
  const headings = Array.from(document.querySelectorAll('h2'));
  const target = headings.find(h => h.textContent.trim() === '临时模型');
  if (!target) return { ok: false, reason: 'heading not found' };
  const r = target.getBoundingClientRect();
  // 也定位父节区段（直到下一个 h2），便于圈出整段
  let section = target.parentElement;
  const sr = section.getBoundingClientRect();
  return {
    ok: true,
    headingRect: { x: r.x, y: r.y, w: r.width, h: r.height },
    sectionRect: { x: sr.x, y: sr.y, w: sr.width, h: sr.height },
    sectionTag: section.tagName,
    docHeight: document.documentElement.scrollHeight,
    scrollY: window.scrollY,
  };
})()

